}", "originalFile": "//! Truncation of Parquet column statistics (min/max bounds) for binary and
//! UTF-8 string columns.
//!
//! Storing the full min/max value of a column that contains very large
//! strings/binaries would bloat the file's metadata (potentially by megabytes).
//! The Parquet spec allows these bounds to be *truncated* as long as the
//! truncated `min` is still `<=` every value and the truncated `max` is still
//! `>=` every value in the column.
//!
//! The truncation length is configurable through the
//! `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` environment variable and
//! defaults to 64 bytes. Setting it to `0` disables truncation entirely.

use std::sync::OnceLock;

const DEFAULT_TRUNCATE_LEN: usize = 64;

/// Returns the configured statistics truncation length in bytes.
///
/// Reads `POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN` once (the result is
/// cached for the lifetime of the process). A value of `0` means truncation is
/// disabled. When the variable is unset or cannot be parsed, the default of
/// [`DEFAULT_TRUNCATE_LEN`] bytes is used.
pub(crate) fn truncate_len() -> usize {
    static TRUNCATE_LEN: OnceLock<usize> = OnceLock::new();
    *TRUNCATE_LEN.get_or_init(|| {
        std::env::var("POLARS_PARQUET_BINARY_STATISTICS_TRUNCATE_LEN")
            .ok()
            .and_then(|v| v.parse::<usize>().ok())
            .unwrap_or(DEFAULT_TRUNCATE_LEN)
    })
}

/// Truncate a `min` statistic for a binary or UTF-8 string column, honoring the
/// configured truncation length.
///
/// Values that already fit within the limit (or when truncation is disabled)
/// are returned unchanged.
pub(crate) fn truncate_min_statistic(value: Vec<u8>, is_utf8: bool) -> Vec<u8> {
    let limit = truncate_len();
    if limit == 0 || value.len() <= limit {
        return value;
    }
    if is_utf8 {
        truncate_utf8_min(&value, limit)
    } else {
        truncate_binary_min(&value, limit)
    }
}

/// Truncate a `max` statistic for a binary or UTF-8 string column, honoring the
/// configured truncation length.
///
/// Values that already fit within the limit (or when truncation is disabled)
/// are returned unchanged. Returns `None` if no valid upper bound could be
/// produced, in which case the `max` statistic should be omitted.
pub(crate) fn truncate_max_statistic(value: Vec<u8>, is_utf8: bool) -> Option<Vec<u8>> {
    let limit = truncate_len();
    if limit == 0 || value.len() <= limit {
        return Some(value);
    }
    if is_utf8 {
        truncate_utf8_max(&value, limit)
    } else {
        truncate_binary_max(&value, limit)
    }
}

/// Truncate a `min` statistic for a UTF-8 string column.
///
/// Returns the longest valid UTF-8 prefix of `value` that fits within `limit`
/// bytes. Because the result is a prefix of `value`, it is guaranteed to be
/// `<=` `value`.
pub(crate) fn truncate_utf8_min(value: &[u8], limit: usize) -> Vec<u8> {
    value[..utf8_prefix_len(value, limit)].to_vec()
}

/// Truncate a `max` statistic for a UTF-8 string column.
///
/// Returns the longest valid UTF-8 prefix of `value` that fits within `limit`
/// bytes, with its last character incremented so that the result is a valid
/// upper bound (`>=` `value`). Incrementing preserves the UTF-8 encoded byte
/// length of the character. Returns `None` if no valid upper bound could be
/// produced (in which case the `max` statistic should be omitted).
pub(crate) fn truncate_utf8_max(value: &[u8], limit: usize) -> Option<Vec<u8>> {
    let prefix = &value[..utf8_prefix_len(value, limit)];
    increment_utf8(prefix)
}

/// Truncate a `min` statistic for a binary column.
///
/// Truncates `value` to exactly `limit` bytes (a byte-level prefix). The result
/// is `<=` `value`.
pub(crate) fn truncate_binary_min(value: &[u8], limit: usize) -> Vec<u8> {
    value[..limit].to_vec()
}

/// Truncate a `max` statistic for a binary column.
///
/// Truncates `value` to at most `limit` bytes and produces a valid upper bound
/// by incrementing the last non-`0xFF` byte within the limit. If every byte
/// within the limit is `0xFF`, the search continues *beyond* the limit to find
/// the first non-`0xFF` byte, which is then incremented. Returns `None` if the
/// entire value is `0xFF` (no valid upper bound exists), in which case the
/// `max` statistic should be omitted.
pub(crate) fn truncate_binary_max(value: &[u8], limit: usize) -> Option<Vec<u8>> {
    // First look for a byte to increment within the truncation limit.
    for i in (0..limit).rev() {
        if value[i] != 0xFF {
            let mut result = value[..=i].to_vec();
            result[i] += 1;
            return Some(result);
        }
    }

    // Every byte within the limit is 0xFF. Extend the search past the limit so
    // that we can still produce a valid (if longer) upper bound.
    for i in limit..value.len() {
        if value[i] != 0xFF {
            let mut result = value[..=i].to_vec();
            result[i] += 1;
            return Some(result);
        }
    }

    // The whole value is 0xFF: no finite upper bound can be represented.
    None
}

/// Length in bytes of the longest valid UTF-8 prefix of `value` that fits
/// within `limit` bytes (i.e. the largest UTF-8 char boundary `<= limit`).
fn utf8_prefix_len(value: &[u8], limit: usize) -> usize {
    if value.len() <= limit {
        return value.len();
    }
    let mut end = limit;
    // `value` is valid UTF-8, so walk back to the nearest char boundary.
    while end > 0 && !is_utf8_char_boundary(value[end]) {
        end -= 1;
    }
    end
}

/// Whether `byte` is the first byte of a UTF-8 code point (i.e. not a
/// continuation byte `0b10xx_xxxx`).
fn is_utf8_char_boundary(byte: u8) -> bool {
